function formatPercent(value) {
                return typeof value === 'number' ? `${(value * 100).toFixed(1)}%` : 'ND';
            }

            function formatNumber(value) {
                return typeof value === 'number' ? value.toFixed(1) : 'ND';
            }

            function formatNormalizedDistance(value) {
                return typeof value === 'number' ? `${((1 - value) * 100).toFixed(1)}%` : 'ND';
            }

            function setText(element, value) {
                element.textContent = value;
            }

            function scrollLogToBottom() {
                requestAnimationFrame(() => {
                    backendLog.scrollTop = backendLog.scrollHeight;
                });
            }

            function filterLogText(logText) {
                if (typeof logText !== 'string') {
                    return '';
                }

                return logText
                    .split('\n')
                    .filter((line) => /\b(WARNING|ERROR|CRITICAL)\b/.test(line))
                    .join('\n');
            }
